async function l(xs: number[]): Promise<number> { for (const x of xs) { if (x > 1) return Promise.resolve(x); } return -1; }
async function s(xs: string[]): Promise<string> { for (const x of xs) { return Promise.resolve(x); } return 'none'; }
async function main(): Promise<void> { console.log(await l([1, 2, 3])); console.log(await l([0, 1])); console.log(await s(['a', 'b'])); console.log(await s([])); }
